// Independently authored learning content. No private Base44 records are included.
part 'extended_content.dart';
class Topic {
  const Topic(this.id, this.chapter, this.title, {this.goal = '', this.lesson = '', this.example = '', this.output = ''});
  final String id, title, goal, lesson, example, output;
  final int chapter;
  bool get ready => lesson.isNotEmpty;
}
const chapters = ['Functions and Variables', 'Conditionals', 'Loops', 'Exceptions', 'Libraries', 'Unit Tests', 'File I/O', 'Regular Expressions', 'Object-Oriented Programming', 'Et Cetera', 'Final Project and Course Assessment'];
const starterTopics = <Topic>[
  Topic('python-c0-t0', 0, 'Running and saving Python programs', goal: 'Save a Python file and recognise its output.', lesson: 'A program is a sequence of instructions. Save Python source as a file ending in .py. Running the file asks Python to execute it. Saving changes and running again are separate actions. The workspace below runs a copy of your code; Download keeps a .py copy on your device.\n\nprint sends a value to the output. Quotes identify literal text and are not part of the printed message. Predict the result, then run the example and change the message.\n\nPython source and program output serve different purposes. The source describes instructions; output is evidence from one execution. This terminal runs the current editor contents. A downloaded file is a separate saved copy. When a result surprises you, check which program was run and whether the source changed after that run.', example: 'print("My first program")', output: 'My first program'),
  Topic('python-c0-t1', 0, 'print, strings, and comments', goal: 'Distinguish program text, string data and comments.', lesson: 'A string represents text. Put it inside matching single or double quotes. print displays values. A comment begins with # outside a string and continues to the end of the line. Python ignores that comment when executing the program.\n\nA # inside quotes is ordinary string data. Code indentation and spelling matter. Compare your prediction with the output before changing this example.\n\nEscaped characters such as \\n represent characters inside a string rather than a new Python statement. print can receive several values and controls how they are separated and how the output ends. Test one change at a time so you can identify which setting changed the display.', example: 'print("# is text here")\n# This line is a comment\nprint("Done")', output: '# is text here\nDone'),
  Topic('python-c0-t2', 0, 'Variables and assignment', goal: 'Trace the current value of a variable.', lesson: 'Assignment evaluates the right side and binds the resulting value to a name. It is not an equation that remains linked forever. Read statements from top to bottom and record each value as it changes.\n\nNames help explain a program: total is more useful than a for a running sum. Reassigning one variable does not repeat an earlier assignment to another variable.\n\nAn assignment can change the type of value bound to a name; Python names are not permanently restricted to the type of their first value. Trace the value after each statement. Two names referring to a mutable object may observe the same mutation; that is a later topic and differs from reassigning an integer name.', example: 'total = 10\nsnapshot = total\ntotal = total + 3\nprint(total)\nprint(snapshot)', output: '13\n10'),
  Topic('python-c0-t3', 0, 'input and string methods', goal: 'Read text and store a cleaned result.', lesson: 'input returns a string. In this runner enter each response on a separate line in Program input before running. The program can display a prompt, but the prompt is separate from its result.\n\nstrip returns a new string with surrounding whitespace removed. It does not remove spaces in the middle. Store the returned value. An f-string inserts the value of an expression between braces.\n\nString methods return new string values because strings are immutable. Calling a method without storing or using its result does not replace your original variable. Compare leading spaces, trailing spaces and spaces between words. The terminal input box supplies one response per line; prompt text is shown separately from output.', example: 'city = input("City: ").strip()\nprint(f"Destination: {city}")', output: 'With input Nottingham: Destination: Nottingham'),
  Topic('python-c0-t4', 0, 'Numbers and conversion', goal: 'Convert valid numeric text before calculating.', lesson: 'The string "7" is text; the integer 7 is a number. Joining two strings and adding two numbers do different things. Convert valid integer text using int and decimal text using float. Invalid conversions raise an exception.\n\nDo not silently assume that an input is a number. These opening exercises explicitly supply valid numeric input. Decimal formatting controls display, not the precision of the stored value.\n\nint accepts valid integer text; float accepts decimal text. A conversion can fail with ValueError. An integer and a float may print differently even when they represent the same numeric amount. Floating-point values can approximate decimals, so choose a stated tolerance when testing a calculation and a format when displaying it.', example: 'print("7" + "2")\nprint(int("7") + int("2"))', output: '72\n9'),
  Topic('python-c0-t5', 0, 'Arithmetic and formatted output', goal: 'Calculate first and format the result for display.', lesson: 'Python uses +, -, *, /, //, %, and ** for arithmetic. Multiplication is evaluated before addition; parentheses can change the grouping. // performs floor division and % gives a remainder.\n\nAn f-string format such as :.2f displays two decimal places. Calculate a value first, then decide how it should be presented. Try the example and explain the difference between the first two results.\n\nParentheses make intended grouping explicit. Division with / and floor division with // serve different purposes. Test both positive and negative examples before assuming that floor division simply removes decimal digits. A correct calculation and a correctly formatted result are separate checks.', example: 'print(3 + 2 * 5)\nprint((3 + 2) * 5)\namount = 4.5 * 2\nprint(f"Amount: {amount:.2f}")', output: '13\n25\nAmount: 9.00'),
  Topic('python-c0-t6', 0, 'Functions and parameters', goal: 'Define a reusable operation with an explicit input.', lesson: 'def creates a function. Its indented body runs when the function is called. A parameter is a local name for an argument supplied by the caller.\n\nA function should have a clear purpose. Calling the same function with different inputs avoids copying its body. Predict both lines in this example and then add another call.\n\nEach function call creates a new local execution context. Parameter names belong to that call. Arguments supply values at a call site, while parameters name them inside the function. A default argument can make a parameter optional, but the function should still have a clear contract about what it does.', example: 'def greet(name):\n    print(f"Welcome, {name}")\n\ngreet("Amina")\ngreet("Musa")', output: 'Welcome, Amina\nWelcome, Musa'),
  Topic('python-c0-t7', 0, 'Return values and program structure', goal: 'Separate calculating a result from displaying it.', lesson: 'return sends a value back to the caller and ends that function call. print displays a value but does not supply it as the useful result of your function. Store or use a return value at the call site.\n\nSeparating calculation and presentation makes tests easier: a test can call the calculation without reading printed messages. Keep names and arguments meaningful.\n\nA function without an explicit return produces None. A return statement ends that call, so statements after it on the same path do not run. A calculation can be called by a terminal interface, a test, or another function. A main function and main guard can organise a script without running its interface merely because the file is imported.', example: 'def double(number):\n    return number * 2\n\nresult = double(6)\nprint(result)', output: '12'),
];
