  1: ['Comparisons and Boolean values', 'if, elif, and else', 'and, or, and not', 'Boundary values and decision tables', 'Nested conditions', 'Truthiness and match statements'],
  2: ['while loops and termination', 'for loops and range', 'Lists and iteration', 'Dictionaries and iteration', 'Counters and accumulators'],
  3: ['Understanding an exception traceback', 'Recovering from invalid numeric input', 'Raising and propagating errors'],
  4: ['Importing a standard library module', 'Choosing an API and reading its documentation', 'Isolating project dependencies'],
  5: ['Checking a function with assert', 'Testing boundaries and failure cases', 'Writing an independent test suite'],
  6: ['Opening, reading and closing a text file', 'Writing structured records', 'Validating loaded data'],
  7: ['Matching a simple text pattern', 'Searching and extracting a group', 'Testing a pattern against edge cases'],
  8: ['Defining a class and creating objects', 'Separating instance data from class data', 'Designing a small object interface'],
  9: ['Comprehensions and generators', 'Describing interfaces with type hints', 'Refactoring a program without changing its behaviour'],
  10: ['Planning a final project', 'Collecting evidence and tests', 'Final assessment and reflection'],
};
List<Topic> get courseTopics => [...starterTopics, ...extendedTopics];
Topic topicById(String id) => courseTopics.firstWhere((t) => t.id == id);

class Exercise {
  const Exercise({required this.id, required this.topic, required this.category, required this.type, required this.title, required this.prompt, this.options = const [], this.answer = '', this.accepted = const [], this.tests = const [], this.hints = const [], this.solution = '', this.required = true});
  final String id, topic, category, type, title, prompt, answer, solution;
  final List<String> options, accepted, hints;
  final List<Map<String, dynamic>> tests;
  final bool required;
  Map<String, dynamic> get marking => {'id': id, 'type': type, 'answer': answer, 'accepted': accepted, 'tests': tests};
}
const starterExercises = <Exercise>[
  Exercise(id:'starter-choice', topic:'python-c0-t0', category:'Classwork', type:'choice', title:'Predict before running', prompt:'What does print("Ready") display?', options:['The word Ready','The quotes and the word Ready','Nothing','A file named Ready'], answer:'0', hints:['Quotes mark a string in the source code.'], solution:'Ready is displayed without its surrounding quotes.'),
  Exercise(id:'starter-code', topic:'python-c0-t0', category:'Homework', type:'code', title:'A clear status message', prompt:'Print exactly one line: Setup complete. You may use any correct Python implementation.', tests:[{'input':<String>[], 'expected':'Setup complete.'}], hints:['What must a person see when the program finishes?'], solution:'print("Setup complete.")'),
  Exercise(id:'starter-transfer', topic:'python-c0-t0', category:'Challenge', type:'written', title:'Explain the workflow', prompt:'You changed your source file but the old output is still on screen. Explain two actions you would check, and why.', hints:['Saving a file and running a file are separate actions.'], required:false),
  Exercise(id:'strings-choice', topic:'python-c0-t1', category:'Classwork', type:'choice', title:'A comment or data?', prompt:'Which line prints a # character?', options:['# print("Hi")','print("# Hi")','print(Hi)','All three'], answer:'1', solution:'A # within quotes is string data.'),
  Exercise(id:'strings-code', topic:'python-c0-t1', category:'Homework', type:'code', title:'Two lines of output', prompt:'Print Alpha and Omega on separate lines, in that order.', tests:[{'input':<String>[], 'expected':'Alpha\nOmega'}], hints:['Compare the required number of output lines with what your program produces.'], solution:'print("Alpha")\nprint("Omega")'),
  Exercise(id:'variables-choice', topic:'python-c0-t2', category:'Classwork', type:'short', title:'Trace an update', prompt:'x = 8; y = x; x = x + 2. What value is now stored in y? Enter the number only.', accepted:['8'], solution:'y remains 8 because its assignment happened before x changed.'),
  Exercise(id:'variables-code', topic:'python-c0-t2', category:'Homework', type:'code', title:'Calculate a remaining balance', prompt:'Read two valid integer inputs: initial balance, then amount spent. Print the remaining balance as an integer.', tests:[{'input':['20','7'],'expected':'13'},{'input':['7','7'],'expected':'0'},{'input':['100','1'],'expected':'99'}], hints:['Identify what each entered value represents before choosing your calculation.'], solution:'balance = int(input())\nspent = int(input())\nprint(balance - spent)'),
  Exercise(id:'input-choice', topic:'python-c0-t3', category:'Classwork', type:'choice', title:'Understand strip', prompt:'What is the result of "  New Town  ".strip()?', options:['NewTown','  New Town','New Town','new town'], answer:'2', solution:'Only surrounding whitespace is removed.'),
  Exercise(id:'input-code', topic:'python-c0-t3', category:'Homework', type:'code', title:'A clean label', prompt:'Read one line of text, remove surrounding whitespace, and print Label: followed by one space and the cleaned text.', tests:[{'input':['  Green Park  '],'expected':'Label: Green Park'},{'input':['Library'],'expected':'Label: Library'}], hints:['Which spaces are part of the name, and which were only around it?'], solution:'label = input().strip()\nprint(f"Label: {label}")'),
  Exercise(id:'numbers-choice', topic:'python-c0-t4', category:'Classwork', type:'short', title:'Text or addition?', prompt:'What does int("6") + int("4") produce? Enter the number only.', accepted:['10'], solution:'Both strings convert to integers, so addition produces 10.'),
  Exercise(id:'numbers-code', topic:'python-c0-t4', category:'Homework', type:'code', title:'Add two valid integers', prompt:'Read two valid integer inputs and print their sum as one integer line.', tests:[{'input':['6','4'],'expected':'10'},{'input':['-5','2'],'expected':'-3'},{'input':['0','0'],'expected':'0'}], hints:['What type of value does your operation need?'], solution:'first = int(input())\nsecond = int(input())\nprint(first + second)'),
  Exercise(id:'arithmetic-choice', topic:'python-c0-t5', category:'Classwork', type:'short', title:'Operation order', prompt:'What is the value of 4 + 3 * 2? Enter the number only.', accepted:['10'], solution:'Multiplication is evaluated first: 4 + 6 is 10.'),
  Exercise(id:'arithmetic-code', topic:'python-c0-t5', category:'Homework', type:'code', title:'Rectangle perimeter', prompt:'Read two valid positive decimal inputs: width and height. Print Perimeter: followed by one space and the perimeter to two decimal places.', tests:[{'input':['3','4'],'expected':'Perimeter: 14.00'},{'input':['1.5','2'],'expected':'Perimeter: 7.00'}], hints:['Draw the shape and label the quantity the question asks for.','Compare the presentation of your result with the required format.'], solution:'width = float(input())\nheight = float(input())\nprint(f"Perimeter: {2 * (width + height):.2f}")'),
  Exercise(id:'arithmetic-transfer', topic:'python-c0-t5', category:'Challenge', type:'code', title:'Full packs', prompt:'A shop sells notebooks in packs of 4. Read a valid nonnegative integer number of notebooks needed. Print the smallest number of packs sufficient for that count. Use arithmetic without conditions or loops.', tests:[{'input':['0'],'expected':'0'},{'input':['1'],'expected':'1'},{'input':['4'],'expected':'1'},{'input':['5'],'expected':'2'},{'input':['17'],'expected':'5'}], hints:['A partially used pack still counts.'], solution:'needed = int(input())\nprint((needed + 3) // 4)', required:false),
  Exercise(id:'functions-choice', topic:'python-c0-t6', category:'Classwork', type:'choice', title:'When does a body run?', prompt:'When does the body of a normal function run?', options:['When the file is saved','Every time def is read','When the function is called','Only when Python starts'], answer:'2', solution:'def creates the function; a call executes its body.'),
  Exercise(id:'functions-code', topic:'python-c0-t6', category:'Homework', type:'code', title:'A reusable greeting', prompt:'Read one name and print Welcome, NAME with the entered name replacing NAME. Use a function.', tests:[{'input':['Sara'],'expected':'Welcome, Sara'},{'input':['Mo'],'expected':'Welcome, Mo'}], hints:['Which part should vary between two runs?'], solution:'def welcome(name):\n    print(f"Welcome, {name}")\n\nwelcome(input())'),
  Exercise(id:'return-choice', topic:'python-c0-t7', category:'Classwork', type:'choice', title:'Return and display', prompt:'What is the main purpose of return?', options:['To show a value on screen','To send a value to the caller','To save a file','To create a global variable'], answer:'1', solution:'return supplies the result of a call to its caller.'),
  Exercise(id:'return-code', topic:'python-c0-t7', category:'Homework', type:'code', title:'A useful result', prompt:'Read a valid integer and print its square. Your calculation function must return its result.', tests:[{'input':['5'],'expected':'25'},{'input':['-3'],'expected':'9'},{'input':['0'],'expected':'0'}], hints:['What value does the caller need to receive?'], solution:'def square(number):\n    return number * number\n\nprint(square(int(input())))'),
  Exercise(id:'opening-project', topic:'python-c0-t7', category:'Project', type:'code', title:'Opening chapter project: event budget', prompt:'Read a valid nonnegative integer guest count and a valid nonnegative decimal cost per guest. Print Total: followed by one space and the total to two decimal places. Include a calculation function, meaningful names, and an explanation of two test cases in My Notes. Save your explanation in My Notes.', tests:[{'input':['3','2.5'],'expected':'Total: 7.50'},{'input':['0','9'],'expected':'Total: 0.00'},{'input':['12','1.25'],'expected':'Total: 15.00'}], hints:['List the inputs and final result. Which part of your plan remains unclear?'], solution:'def total_cost(guests, per_guest):\n    return guests * per_guest\n\nguests = int(input())\ncost = float(input())\nprint(f"Total: {total_cost(guests, cost):.2f}")'),
];
List<Exercise> get exercises => [...starterExercises, ...extendedExercises];
List<Exercise> forTopic(String topic, String category) => exercises.where((e) => e.topic == topic && e.category == category).toList();
